C(7, 1, "Tolera el enojo", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Te cuesta decirle que no a tu hijo? ¿Sobre todo cuando se enoja?"),
 ("joven", "rewe", "[adolescente, enojado, directo] ¡Qué injusto eres!"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Límites con los adolescentes, de John Townsend, tiene un subtítulo que lo dice todo: cuándo decir sí, y cómo decir no. Y entre sus consejos está que, aun cuando tu hijo esté enojado contigo, procures seguir conectado con él."),
 ("cita", "marisol", "[firme, cálido, pausado] Y da una pauta incómoda: «Tolere el enojo de su adolescente». A menos que lo estés maltratando seriamente, déjalo enojarse y no te apartes."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Es decir: déjalo enojarse, no te apartes, escúchalo y entiende lo que te dice. Que se enoje porque dijiste que no, no significa que hayas fallado."),
 ("papa", "mario", "[papá, tranquilo, firme] Entiendo que te enojes. Mi respuesta sigue siendo no."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: la próxima vez que digas que no, dilo con calma y deja que se enoje. Sin gritar, sin dar vueltas. No tienes que convencerlo de que está de acuerdo."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: libertad para elegir, y consecuencias reales."),
], [
 ("titular", "gancho", "no", "¿Te cuesta decir «no»?", "La palabra «no» grande, con un temblor y luego firme"),
 ("reaccion", "joven", "injusto", "¡Qué injusto eres!", "Burbuja de enojo del adolescente"),
 ("titular", "idea", "subtítulo", "Cuándo decir sí, cómo decir no", "Dos botones: «sí» y «no», uno a cada lado"),
 ("icono", "idea", "conectado", "Conectado, aun enojado", "Dos clavijas de enchufe que siguen unidas mientras una chispea"),
 ("cita", "cita", "Tolere", "«Tolere el enojo de su adolescente»", "Tarjeta de cita: John Townsend, Límites con los adolescentes"),
 ("icono", "giro", "fallado", "Su enojo no es tu fracaso", "Palomita amarilla sobre una burbuja de enojo"),
 ("titular", "giro", "escúchalo", "No te apartes: escúchalo", "Oreja estilizada junto a una burbuja de enojo"),
 ("reaccion", "papa", "Entiendo", "Entiendo que te enojes. Mi respuesta sigue siendo no.", "Burbuja de papá, tono sereno"),
 ("accion", "accion", "calma", "Para hoy: di que no, con calma", "Tarjeta «Para hoy» con una respiración"),
 ("titular", "siguiente", "consecuencias", "Siguiente: libertad y consecuencias reales", "Dos flechas: «elijo» y «resultado»"),
], [GB + ", Townsend: «Tolere el enojo de su adolescente» (PT387)"])

C(7, 2, "Libertad y consecuencias", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Cuántas veces has intentado hacer que tu hijo saque buenas notas? ¿Y ha funcionado?"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Townsend propone dejar de intentar hacer que tu hijo saque buenas notas, que te respete o que sea responsable. Y ofrece otro camino: más libertad de elección, y que viva las consecuencias."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] O sea, que tu hijo elija más cosas, y que le toque vivir el resultado de lo que elige. Así, dice el libro, aprenderá lo que es la responsabilidad."),
 ("papa", "mario", "[papá, dudoso, preocupado] ¿Y si le va mal? Pero si no le insisto, no lo hace."),
 ("cita", "marisol", "[firme, cálido, pausado] Y propone esta regla: «Sea blando en cuanto a las preferencias y el estilo, pero duro con la falta de respeto y el egoísmo»."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: elige una decisión pequeña que hoy tomas tú por tu hijo, y devuélvesela. La ropa, la hora de hacer la tarea, qué desayunar. Una sola. Solo hoy."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: cuando la distancia también es cosa tuya."),
], [
 ("titular", "gancho", "hacer", "¿«Hacer» que...?", "Palabra «hacer» tachada con trazo amarillo"),
 ("icono", "idea", "libertad", "Más libertad de elección", "Candado que se abre"),
 ("icono", "idea", "consecuencias", "Vivir las consecuencias", "Fichas de dominó que caen en cadena"),
 ("titular", "giro", "responsabilidad", "Así se aprende responsabilidad", "«responsabilidad» en morado con subrayado amarillo"),
 ("reaccion", "papa", "mal", "¿Y si le va mal?", "Burbuja de papá con duda"),
 ("cita", "cita", "blando", "«Sea blando en cuanto a las preferencias y el estilo, pero duro con la falta de respeto y el egoísmo»", "Tarjeta de cita: John Townsend, Límites con los adolescentes"),
 ("icono", "cita", "preferencias", "Blando: preferencias · Duro: respeto", "Cojín a la izquierda, roca a la derecha"),
 ("accion", "accion", "decisión", "Para hoy: devuélvele una decisión pequeña", "Tarjeta «Para hoy» con una llave que pasa de mano"),
 ("icono", "accion", "ropa", "La ropa · La tarea · El desayuno", "Tres íconos que entran uno a uno"),
 ("titular", "siguiente", "distancia", "Siguiente: cuando la distancia también es tuya", "Dos puntos separados que se acercan"),
], [GB + ", Townsend: «Sea blando en cuanto a las preferencias…» (PA260)"])

C(7, 3, "Revisa tu parte", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] Si sientes lejos a tu hijo, a lo mejor conviene revisar tu parte."),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Townsend plantea que, cuando te sientes desconectado de tu adolescente, el problema puede estar de tu lado y no del suyo. Vale la pena revisarlo primero."),
 ("cita", "marisol", "[firme, cálido, pausado] Y da una regla muy práctica para las salidas: «No irás hasta que hable con los padres»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Es decir, llama a los padres de la casa donde tu hijo quiere ir. Townsend cuenta que esa sencilla regla le ha ahorrado muchas penas, y que los demás padres aprecian la llamada. Además, te acerca a su mundo."),
 ("papa", "mario", "[papá, tranquilo, amable] Buenas tardes. Mi hijo quiere ir a su casa. ¿Cuál es el plan?"),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: cuando tu hijo te pida permiso para salir, pregúntale con quién y dónde, con curiosidad y no con interrogatorio."),
 ("tarjeta", "marisol", TARJ + "Límites con los adolescentes, de John Townsend, de Editorial Vida. Este video no sustituye la lectura del libro."),
], [
 ("titular", "gancho", "parte", "Revisa tu parte", "Espejo pequeño con silueta, sin rostro"),
 ("icono", "idea", "desconectado", "Desconectado: ¿de qué lado está el problema?", "Dos clavijas de enchufe separadas; una se acerca"),
 ("cita", "cita", "irás", "«No irás hasta que hable con los padres»", "Tarjeta de cita: John Townsend, Límites con los adolescentes"),
 ("icono", "giro", "llama", "Llama a los padres de la casa", "Celular con timbre y una casa al fondo"),
 ("titular", "giro", "mundo", "Y te acerca a su mundo", "Puerta que se abre sobre un mapa pequeño"),
 ("reaccion", "papa", "plan", "¿Cuál es el plan?", "Burbuja de papá amable"),
 ("accion", "accion", "permiso", "Para hoy: pregunta con quién y dónde", "Tarjeta «Para hoy»"),
 ("icono", "accion", "curiosidad", "Con curiosidad, no con interrogatorio", "Signo de interrogación suave junto a una lupa tachada"),
 ("tarjeta_libro", "tarjeta", "Vida", "Límites con los adolescentes · John Townsend · Editorial Vida", "Tarjeta de cierre estándar de la serie: portada tipográfica, sin foto; leyenda «Este video no sustituye la lectura del libro»"),
], [GB + ", Townsend: «No irás hasta que hable con los padres» (PT338); problema «puede ser suyo» (PT274)"])
